import java.io.BufferedReader; import java.io.InputStreamReader; import java.util.StringTokenizer; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line1 = br.readLine(); if (line1 == null) return; int n = Integer.parseInt(line1.trim()); int[] a = new int[n]; StringTokenizer st = new StringTokenizer(br.readLine()); for (int i = 0; i < n; i++) { a[i] = Integer.parseInt(st.nextToken()); } long totalSum = 0; for (int i = 0; i < n; i++) { boolean[] present = new boolean[n + 2]; int mex = 1; for (int j = i; j < n; j++) { if (a[j] <= n + 1) { present[a[j]] = true; } while (present[mex]) { mex++; } totalSum += mex; } } System.out.println(totalSum); } }